def running_mean(nums):
    out, s = [], 0.0
    for i, x in enumerate(nums, 1):
        s += x
        out.append(s / i)
    return out

def dot_product(a, b):
    if len(a) != len(b): raise ValueError('mismatch')
    return sum(x * y for x, y in zip(a, b))

